spec: CipherSpec
rule: Cipher.crysl
creation: g1 g2 g3
accepting: end
g1 -> javax.crypto.Cipher.getInstance(java.lang.String)
g2 -> javax.crypto.Cipher.getInstance(java.lang.String, AnyType)
