i2 -> javax.crypto.Cipher.init(int, java.security.Key) | javax.crypto.Cipher.init(int, java.security.Key, java.security.AlgorithmParameters) | javax.crypto.Cipher.init(int, java.security.Key, java.security.AlgorithmParameters, java.security.SecureRandom) | javax.crypto.Cipher.init(int, java.security.Key, java.security.SecureRandom) | javax.crypto.Cipher.init(int, java.security.Key, java.security.spec.AlgorithmParameterSpec) | javax.crypto.Cipher.init(int, java.security.Key, java.security.spec.AlgorithmParameterSpec, java.security.SecureRandom)
